referenceSolutions.javascript:
export function solve(value) {
  let current = value;
  while (
    current !== null &&
    typeof current === "object" &&
    !Array.isArray(current) &&
    current.kind === "resolve"
  )
    current = current.value;
  if (
    current !== null &&
    typeof current === "object" &&
    !Array.isArray(current) &&
    current.kind === "reject"
  )
    return { status: "rejected", value: current.value };
  return { status: "fulfilled", value: current };
}

